#include <stdio.h>
#include <sys/mman.h>

#define SUB (256 << 10)            /* 256 KiB per size class */
static const size_t cls[3] = {32, 64, 128};
static char *base;                 /* one mmap'd region, 3 parts */
static char *bump[3];              /* next never-used slot per class */
static void *freelist[3];          /* LIFO list of freed slots */

static int class_of(size_t n) {
    for (int c = 0; c < 3; c++)
        if (n <= cls[c]) return c;
    return -1;                     /* too big: a real allocator mmaps it */
}

void sc_init(void) {
    base = mmap(NULL, 3 * SUB, PROT_READ | PROT_WRITE,
                MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    for (int c = 0; c < 3; c++) bump[c] = base + c * SUB;
}

void *sc_alloc(size_t n) {
    int c = class_of(n);
    if (c < 0) return NULL;
    if (freelist[c]) {             /* reuse: pop the list head */
        void *p = freelist[c];
        freelist[c] = *(void **)p;
        return p;
    }
    if (bump[c] + cls[c] > base + (c + 1) * SUB) return NULL;
    void *p = bump[c];             /* carve a fresh slot */
    bump[c] += cls[c];
    return p;
}

void sc_free(void *p) {            /* no size needed: the address */
    int c = ((char *)p - base) / SUB;  /* says which class owns it */
    *(void **)p = freelist[c];     /* the free slot holds the link */
    freelist[c] = p;
}

#include <stdio.h>
#include <stddef.h>
void sc_init(void); void *sc_alloc(size_t); void sc_free(void *);

int main(void) {
    static void *p[3000]; static size_t want[3000];
    size_t asked = 0, given = 0;
    unsigned x = 12345;
    sc_init();
    for (int i = 0; i < 3000; i++) {
        x = x * 1103515245u + 12345u;          /* fixed pseudo-random */
        want[i] = 1 + (x >> 16) % 128;         /* sizes 1..128 */
        p[i] = sc_alloc(want[i]);
        size_t got = want[i] <= 32 ? 32 : want[i] <= 64 ? 64 : 128;
        asked += want[i]; given += got;
    }
    printf("asked %zu B, slots %zu B, waste %.1f%%\n",
           asked, given, 100.0 * (given - asked) / given);
    for (int i = 0; i < 3000; i += 2) sc_free(p[i]);
    void *q = sc_alloc(want[2998]);
    printf("freed p[2998] reused: %s\n", q == p[2998] ? "yes" : "no");
    return 0;
}

