#include <stdio.h>
#include <stdlib.h>
#include <sys/mman.h>

int main(int argc, char **argv) {
    size_t mib = atol(argv[1]), n = mib << 20;
    int huge = argc > 2;                     /* any 3rd arg: ask for THP */
    char *a = mmap(NULL, n, PROT_READ | PROT_WRITE,
                   MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (a == MAP_FAILED) return 1;
    if (huge) madvise(a, n, MADV_HUGEPAGE);
    for (size_t i = 0; i < n; i += 4096) a[i] = 1;   /* fault it all in */
    unsigned long x = 1, sum = 0;
    for (long k = 0; k < 100000000; k++) {    /* 1e8 random reads */
        x = x * 6364136223846793005UL + 1442695040888963407UL;
        sum += a[(x >> 16) % n];
    }
    printf("%lu\n", sum);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <sys/resource.h>

static long minflt(void) {
    struct rusage ru;
    getrusage(RUSAGE_SELF, &ru);
    return ru.ru_minflt;
}

int main(void) {
    size_t n = 64UL << 20;   /* 64 MiB, above the mmap threshold */
    long f0 = minflt();
    char *p = malloc(n);     /* reserves address space only */
    if (!p) return 1;
    long f1 = minflt();
    for (size_t i = 0; i < n; i += 4096)
        p[i] = 1;            /* first write to each 4 KiB page */
    long f2 = minflt();
    printf("malloc: %ld faults, touch: %ld faults\n",
           f1 - f0, f2 - f1);
    free(p);
    return 0;
}

#include <fcntl.h>
#include <stdio.h>
#include <sys/mman.h>
#include <sys/resource.h>
#include <sys/stat.h>

int main(int argc, char **argv) {
    int fd = open(argv[1], O_RDONLY);
    struct stat st;
    if (fd < 0 || fstat(fd, &st) < 0) return 1;
    const unsigned char *p = mmap(NULL, st.st_size, PROT_READ, MAP_PRIVATE, fd, 0);
    if (p == MAP_FAILED) return 1;
    struct rusage a, b;
    getrusage(RUSAGE_SELF, &a);
    unsigned long sum = 0;
    for (off_t i = 0; i < st.st_size; i += 4096)
        sum += p[i];                   /* first read of every page */
    getrusage(RUSAGE_SELF, &b);
    printf("pages %ld  minor %ld  major %ld  (sum %lu)\n",
           (long)((st.st_size + 4095) / 4096),
           b.ru_minflt - a.ru_minflt, b.ru_majflt - a.ru_majflt, sum);
    return 0;
}
